mapper.select:
select
     mn.*
from SYS_Tenant mn

    
        and mn.Te_Type=#{params.teType}
    
    
        and mn.Te_Charge_Type=#{params.teChargeType}
    
    
        and mn.Te_Status=#{params.teStatus}
    
    
        and mn.State=#{params.state}
    
    
        and mn.Te_Industry=#{params.teIndustry}
    
    
        and mn.Te_Size=#{params.teSize}
    
    
        and INSTR(mn.Te_Name,#{params.teName})
    
    
        and INSTR(mn.Te_Code,#{params.teCode})
    
    
        and INSTR(mn.Te_No,#{params.teNo})
    
    
        and INSTR(mn.Te_Legal,#{params.teLegal})
    
    
        and INSTR(mn.Te_Contacts,#{params.teContacts})
    
    
        and INSTR(mn.Te_Contacts_Tel,#{params.teContactsTel})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
